"""Migrated invoiced-order workflow, validation, and total recomputation rules."""

from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENTS = Decimal("0.01")
_ZERO = Decimal("0")


def _numeric(value: Any) -> Decimal:
    """Apply legacy empty/missing numeric coercion."""
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def _is_deleted(row: dict) -> bool:
    return row.get("DEL_FLG") == "Y"


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the I-to-X order fulfilment workflow transition."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    result = order.copy()

    if new_status == "I":
        return result, [], []

    if new_status == "X":
        result["STAT_CD"] = "X"
        return result, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live order-line extensions and the non-frozen order total."""
    result_order = order.copy()
    result_lines = [line.copy() for line in lines]

    # Invoiced and cancelled headers are frozen.  A soft-deleted header was
    # excluded by the legacy nightly query and is likewise not recomputed.
    if order.get("STAT_CD") in ("I", "X") or _is_deleted(order):
        return result_order, result_lines, []

    total = _ZERO

    for source_line, result_line in zip(lines, result_lines):
        if _is_deleted(source_line):
            continue

        extension = _round_cents(
            _numeric(source_line.get("QTY"))
            * _numeric(source_line.get("UNIT_PRC"))
        )
        result_line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _round_cents(
        total * (_numeric(100) - _numeric(order.get("DISC_PCT"))) / _numeric(100)
    )
    result_order["TOT_AMT"] = float(discounted_total)

    if _numeric(order.get("TOT_AMT")) != discounted_total:
        return result_order, result_lines, ["ORD_RETOTAL"]

    return result_order, result_lines, []
